CREATE TABLE email_provider_revisions (tenant_id VARCHAR(64) NOT NULL, revision BIGINT NOT NULL, PRIMARY KEY (tenant_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE email_providers (tenant_id VARCHAR(64) NOT NULL, name VARCHAR(64) NOT NULL, enabled BOOLEAN NOT NULL, default_from TEXT NOT NULL, public_config LONGTEXT NOT NULL, sealed_credentials LONGBLOB NOT NULL, revision BIGINT NOT NULL, PRIMARY KEY (tenant_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE email_templates (tenant_id VARCHAR(64) NOT NULL, name VARCHAR(191) NOT NULL, fields LONGTEXT NOT NULL, revision BIGINT NOT NULL, PRIMARY KEY (tenant_id, name), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE email_notifications (tenant_id VARCHAR(64) NOT NULL, subject_id VARCHAR(191) NOT NULL, purpose VARCHAR(64) NOT NULL, event_key VARCHAR(191) NOT NULL, count INTEGER NOT NULL, expires_at BIGINT NULL, PRIMARY KEY (tenant_id, subject_id, purpose, event_key), KEY email_notifications_expiry (expires_at), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
